// Fit — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, V1_INSTALL_AT_MS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Fit app's origin (see `apps/registry/apps/fit.ts`). */
    readonly VITE_FIT_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/fit` calls: its `ProxyMethod` table in
// `web/fit/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Not allowed, on purpose: `mapRegion.regionsIn` / `mapRegion.catalog` (a route map asks only which
// region covers a point and reads its bytes), and every native-only Fit surface (recording, Takeout,
// auto-import, onboarding — fit-app.md §Web scope → Decided), which has no gateway method anyway.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  // Dashboard
  'fit.dailyAggregates',
  'fit.dailyAggregates.observe',
  // History and detail
  'fit.workoutsPage',
  'fit.workouts.changes',
  'fit.workout',
  'fit.deleteWorkout',
  'fit.importActivityFile',
  // Goals and profile
  'fit.goals',
  'fit.goals.observe',
  'fit.setGoals',
  'fit.profile',
  'fit.profile.observe',
  'fit.setUnits',
  'fit.setName',
  'fit.setBirthDate',
  'fit.setSex',
  'fit.recordHeight',
  'fit.recordWeight',
  // Data sources (read-only)
  'fit.dataSources',
  'fit.dataSources.observe',
  // The workout route map (`@tenshu/map-kit`)
  'mapRegion.regionAt',
  'mapRegion.streamRange',
]

const PROD_ORIGIN = 'https://fit.tenshu.app'

export const fit: HostedApp = {
  id: 'fit',
  order: 40,
  title: 'Fit',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_FIT_ORIGIN',
  devPort: 5180,
  origin: () => appOrigin(import.meta.env.VITE_FIT_ORIGIN, PROD_ORIGIN, 5180),
  methods: METHODS,
  routePath: 'fit/*',
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'fit',
    label: 'Fit',
    description: 'Your activity, end-to-end encrypted.',
    version: '0.1.0',
    installedAtMs: V1_INSTALL_AT_MS,
    launchPath: '/fit',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'fit.read',
        label: 'Read your activity',
        description: 'See your daily activity, workouts, goals, profile and data sources.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'fit.write',
        label: 'Manage your workouts and settings',
        description: 'Import GPX and TCX files, delete workouts, and change your goals, profile and units.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'health',
        label: 'HealthService',
        reason: 'Stores your workouts and daily activity, encrypted client-side.',
      },
      {
        id: 'preference',
        label: 'PreferenceService',
        reason: 'Stores your goals, profile and units.',
      },
      {
        id: 'mapRegion',
        label: 'MapRegionService',
        reason: 'Reads map regions to draw a workout route. Read only.',
      },
    ],
  },
}

export default fit
